import sys
class MockNumPy:
    nan = float('nan')
    def __getattr__(self, name):
        if name == 'NAN':
            raise AttributeError("AttributeError: `np.NAN` was removed in the NumPy 2.0 release. Use `np.nan` instead.")
        raise AttributeError(name)
np = MockNumPy()
try:
    val = np.NAN
except AttributeError as e:
    sys.stderr.write(str(e) + "\n")
    sys.exit(1)
